package dev.pedro.learning.ecommerce.inventory.api;
import dev.pedro.learning.ecommerce.inventory.domain.*; import dev.pedro.learning.ecommerce.inventory.inbox.InboxEventRepository; import jakarta.transaction.Transactional; import jakarta.ws.rs.*; import jakarta.ws.rs.core.MediaType; import java.util.UUID;
@Path("/") @Produces(MediaType.APPLICATION_JSON) public class InventoryResource { private final InventoryItemRepository items; private final InventoryReservationRepository reservations; private final InboxEventRepository inbox; public InventoryResource(InventoryItemRepository items,InventoryReservationRepository reservations,InboxEventRepository inbox){this.items=items;this.reservations=reservations;this.inbox=inbox;}
 @GET @Path("inventory/{productId}") public InventoryItemResponse item(@PathParam("productId")UUID id){var i=items.findById(id);if(i==null)throw new NotFoundException();return InventoryItemResponse.from(i);} @GET @Path("reservations/{orderId}") public ReservationResponse reservation(@PathParam("orderId")UUID id){var r=reservations.findByOrderId(id);if(r==null)throw new NotFoundException();return ReservationResponse.from(r);}
 @GET @Path("admin/inbox/{eventId}") public InboxStatusResponse inbox(@PathParam("eventId")UUID id){var e=inbox.findById(id);return new InboxStatusResponse(e!=null,e==null?"":e.eventType);}
 @PUT @Path("admin/inventory/{productId}/quantity/{quantity}") @Transactional public InventoryItemResponse set(@PathParam("productId")UUID id,@PathParam("quantity")int quantity){if(quantity<0)throw new BadRequestException();var i=items.findById(id);if(i==null){i=new InventoryItem();i.productId=id;i.reservedQuantity=0;items.persist(i);}i.availableQuantity=quantity;return InventoryItemResponse.from(i);}
}
